using namespace std;

using ll = long long;

const int MOD = 1'000'000'007;
const int N = 51;

int n, T;
vector<int> songs[3];
int dp[N][N][N * N][3];
int ways[N][N][N][4];
int fact[N];

int add(int a, int b) {
    a += b;
    if (a >= MOD) a -= MOD;
    return a;
}

int mul(int a, int b) {
    return static_cast<ll>(a) * b % MOD;
}

int calc(int pos, int count, int time, int genre) {
    if (time < 0) return 0;
    if (time == 0 || count == 0)
        return time == 0 && count == 0;
    if (pos >= static_cast<int>(songs[genre].size()))
        return 0;

    int &result = dp[pos][count][time][genre];
    if (result != -1) return result;

    result = add(
        calc(pos + 1, count, time, genre),
        calc(pos + 1, count - 1, time - songs[genre][pos], genre)
    );
    return result;
}

int calcWays(int a, int b, int c, int last) {
    if (a == 0 && b == 0 && c == 0) return 1;

    int &result = ways[a][b][c][last];
    if (result != -1) return result;

    result = 0;
    if (last != 0 && a)
        result = add(result, calcWays(a - 1, b, c, 0));
    if (last != 1 && b)
        result = add(result, calcWays(a, b - 1, c, 1));
    if (last != 2 && c)
        result = add(result, calcWays(a, b, c - 1, 2));

    return result;
}

int main() {
    scanf("%d %d", &n, &T);

    for (int i = 0; i < n; ++i) {
        int duration, genre;
        scanf("%d %d", &duration, &genre);
        songs[genre - 1].push_back(duration);
    }

    memset(dp, -1, sizeof(dp));
    memset(ways, -1, sizeof(ways));

    fact[0] = 1;
    for (int i = 1; i < N; ++i)
        fact[i] = mul(fact[i - 1], i);

    int answer = 0;

    for (int i = 0; i <= static_cast<int>(songs[0].size()); ++i) {
        for (int timeI = 0; timeI <= T; ++timeI) {
            int selectI = calc(0, i, timeI, 0);
            if (selectI == 0) continue;

            for (int j = 0; j <= static_cast<int>(songs[1].size()); ++j) {
                for (int k = 0; k <= static_cast<int>(songs[2].size()); ++k) {
                    int arrangements = calcWays(i, j, k, 3);
                    arrangements = mul(
                        arrangements,
                        mul(fact[i], mul(fact[j], fact[k]))
                    );

                    if (arrangements == 0) continue;

                    for (int timeJ = 0; timeJ <= T - timeI; ++timeJ) {
                        int selectJ = calc(0, j, timeJ, 1);
                        if (selectJ == 0) continue;

                        int timeK = T - timeI - timeJ;
                        int selectK = calc(0, k, timeK, 2);

                        int current = mul(selectI, selectJ);
                        current = mul(current, selectK);
                        current = mul(current, arrangements);
                        answer = add(answer, current);
                    }
                }
            }
        }
    }

    printf("%d\n", answer);
    return 0;
}

